"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["41792"],{33781(e){e.exports=JSON.parse('{"id":"FIN-889","slug":"forecast-period","term":"Forecast Period","also_known_as":[],"difficulty":"Intermediate","definition":"The forecast period is the number of years for which an analyst explicitly projects a company\'s financial results, such as revenue, profit and cash flow, in a valuation model.","explanation":["In a discounted cash flow model, analysts usually forecast detailed cash flows year by year for a set period, often five to ten years. Beyond that, they estimate a terminal value to capture all later cash flows in a single figure.","The forecast period should be long enough for the company to reach a stable state, where its growth rate, profit margins and investment needs have settled at levels that can reasonably be expected to continue. For a mature company, five years may be enough. For a fast-growing company, a longer period, perhaps ten years or more, may be needed so that growth can slow gradually before the terminal value takes over.","For example, an analyst valuing a young technology company might forecast cash flows for ten years, with revenue growth slowing from 30% to 5%, before applying a terminal value.","The choice of forecast period matters. Too short a period may force unrealistic assumptions into the terminal value, which often already accounts for a large share of total value. Too long a period means forecasting further into an uncertain future, where projections become increasingly speculative."],"note":"","total":1500,"prev":{"slug":"forecast-error","term":"Forecast Error"},"next":{"slug":"forecasting","term":"Forecasting"}}')}}]);